package com.dpworld.fms.scheduling;
import java.time.*; import java.util.*; import java.util.concurrent.*;
public final class ResourceReservationService { private final ConcurrentMap<String,Reservation> reservations=new ConcurrentHashMap<>(); public Optional<Reservation> reserve(String resourceId,UUID jobId,Duration ttl){var next=new Reservation(UUID.randomUUID(),resourceId,jobId,Instant.now().plus(ttl));return Optional.ofNullable(reservations.compute(resourceId,(k,old)->old==null||old.expiresAt().isBefore(Instant.now())?next:old)).filter(r->r.id().equals(next.id()));} public void release(String resourceId,UUID jobId){reservations.computeIfPresent(resourceId,(k,r)->r.jobId().equals(jobId)?null:r);} public record Reservation(UUID id,String resourceId,UUID jobId,Instant expiresAt){} }
